BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Noncash consideration included in transaction price at fair value
(2, 'Revenue Recognition', 'Redstone Engineering enters a $500,000 contract to design a warehouse for Oakmont Distributors. In addition to the cash fee, Oakmont will provide Redstone with a parcel of land (fair value $80,000) as partial payment. Under ASC 606, how should Redstone determine the transaction price?', '["$500,000, because noncash consideration is excluded from the transaction price", "$580,000, measuring the land at its fair value and adding it to the cash consideration", "$500,000, because noncash consideration is recognized separately as an investing activity", "$580,000, but only after the land is received and its value is confirmed"]'::jsonb, 1, 'Under ASC 606-10-32-21, noncash consideration is measured at fair value and included in the transaction price. Redstone should include both the $500,000 cash and the $80,000 fair value of the land, totaling $580,000. Choice A is incorrect because noncash consideration is not excluded — ASC 606 explicitly requires its inclusion at fair value.', 'medium', 2),

-- Q2: medium / L3 — Series guidance consolidates substantially similar distinct services into single PO
(2, 'Revenue Recognition', 'Hartwell Cleaning Services enters a 12-month janitorial contract with Briarwood Office Park. Each day''s cleaning is distinct, and the same method (time elapsed) measures progress for each day''s service. The controller classifies each day as a separate performance obligation. Under ASC 606, how should these daily services be classified?', '["As 365 separate performance obligations, each satisfied at a point in time", "As 12 separate performance obligations, one per month", "As a single performance obligation because the daily services form a series of distinct goods that are substantially the same with the same pattern of transfer", "As two performance obligations: weekday cleaning and weekend cleaning"]'::jsonb, 2, 'Under ASC 606-10-25-14(b), a series of distinct goods or services that are substantially the same and have the same pattern of transfer is treated as a single performance obligation. The daily cleaning services meet both criteria — each day is distinct, and time elapsed measures each identically. Choice A is incorrect because the series guidance overrides individual treatment when both criteria are met.', 'medium', 3),

-- Q3: easy / L1 — Contract existence criteria require commercial substance (Step 1)
(2, 'Revenue Recognition', 'Under ASC 606, which of the following is required for a contract with a customer to exist?', '["The contract must have commercial substance", "The contract must be in writing", "The entity must have already begun performing", "The customer must have made an advance payment"]'::jsonb, 0, 'Under ASC 606-10-25-1, one of the five criteria for contract existence is that the contract has commercial substance, meaning the entity''s future cash flows are expected to change. Choice B is incorrect because ASC 606 does not require a written contract — oral and implied contracts also qualify if all five criteria are met.', 'easy', 1),

-- Q4: medium / L2 — Consideration payable to customer reduces transaction price
(2, 'Revenue Recognition', 'Westfield Foods sells products to Grandview Grocers under a contract that includes a $200,000 purchase price and a $15,000 slotting fee paid by Westfield to Grandview for premium shelf space. The shelf space does not represent a distinct good or service. Under ASC 606, what is the transaction price?', '["$200,000, because the slotting fee is a separate marketing expense", "$215,000, because the slotting fee increases the total consideration exchanged", "$200,000, with the slotting fee disclosed separately in the notes", "$185,000, because the slotting fee reduces the transaction price when it does not represent a distinct good or service"]'::jsonb, 3, 'Under ASC 606-10-32-25, consideration payable to a customer is accounted for as a reduction of the transaction price unless the payment is in exchange for a distinct good or service. Since the shelf space is not a distinct service, the $15,000 reduces the transaction price to $185,000. Choice A is incorrect because ASC 606 does not allow separate expense treatment when the consideration is not for a distinct good or service.', 'medium', 2),

-- Q5: medium / L2 — Bill-and-hold arrangement revenue recognition criteria
(2, 'Revenue Recognition', 'Marlow Manufacturing produces custom machinery for Ashton Industries. The machine is complete and ready for delivery, but Ashton requests that Marlow hold it for 60 days due to warehouse renovations. Control has not physically transferred. Under ASC 606, what must Marlow demonstrate for a bill-and-hold arrangement to qualify for revenue recognition?', '["The reason for the arrangement is substantive, the product is separately identified as belonging to the customer, the product is currently ready for transfer, and the entity cannot use the product or direct it to another customer", "The customer has made full payment and signed a nonrefundable purchase agreement", "The entity has obtained insurance on the product naming the customer as beneficiary", "The product has been segregated in a bonded warehouse with the customer holding the key"]'::jsonb, 0, 'Under ASC 606-10-25-30, bill-and-hold revenue recognition requires all four criteria: (1) substantive reason for the arrangement, (2) product separately identified as the customer''s, (3) product currently ready for physical transfer, and (4) entity cannot use or direct the product elsewhere. Choice B is incorrect because payment alone does not satisfy the bill-and-hold criteria — all four conditions must be met regardless of payment status.', 'medium', 2),

-- Q6: medium / L3 — Customer option providing material right is a separate PO
(2, 'Revenue Recognition', 'Crestline Telecom sells a smartphone for $800 and gives the customer a coupon for 40% off any accessory (normally $100–$200) redeemable within 90 days. The discount is not available to other customers. The estimated standalone selling price of the material right is $30. Under ASC 606, how should Crestline account for the coupon?', '["Disclose the coupon as a contingent obligation but recognize the full $800 as revenue at the point of sale", "Treat the coupon as a separate performance obligation and allocate a portion of the $800 transaction price to it based on relative standalone selling prices", "Recognize the coupon as a marketing expense when redeemed", "Defer the entire $800 until the coupon either expires or is redeemed"]'::jsonb, 1, 'Under ASC 606-10-55-41 through 55-45, a customer option to acquire additional goods at a discount that provides a material right is treated as a separate performance obligation. The $800 transaction price must be allocated between the smartphone and the material right based on relative standalone selling prices. Choice C is incorrect because the coupon provides an incremental benefit not available to all customers, making it a material right rather than a marketing cost.', 'medium', 3),

-- Q7: easy / L1 — Assurance-type vs service-type warranty distinction
(2, 'Revenue Recognition', 'Under ASC 606, what is the primary distinction between an assurance-type warranty and a service-type warranty?', '["An assurance-type warranty covers defects arising after delivery, while a service-type warranty covers pre-existing defects", "An assurance-type warranty is always purchased separately, while a service-type warranty is always included", "An assurance-type warranty assures the product meets agreed-upon specifications, while a service-type warranty provides an additional service beyond that assurance", "An assurance-type warranty is recognized as a liability, while a service-type warranty is recognized as revenue immediately"]'::jsonb, 2, 'Under ASC 606-10-25-19 through 25-21, an assurance-type warranty provides assurance that the product meets agreed-upon specifications and is accounted for under ASC 460 (not as a performance obligation). A service-type warranty provides service beyond that assurance and is a separate performance obligation. Choice A is incorrect because assurance-type warranties cover defects existing at the time of sale, not those arising after delivery.', 'easy', 1),

-- Q8: easy / L1 — Contract asset vs receivable distinction
(2, 'Revenue Recognition', 'Under ASC 606, what distinguishes a contract asset from a receivable?', '["A contract asset is reported as noncurrent, while a receivable is always current", "A contract asset arises from cash payments, while a receivable arises from credit sales", "A contract asset requires customer acceptance, while a receivable does not", "A contract asset is conditional on the entity''s future performance, while a receivable is conditional only on the passage of time"]'::jsonb, 3, 'Under ASC 606-10-45-3 and 45-4, a contract asset exists when the entity''s right to consideration is conditional on satisfying additional performance obligations. A receivable exists when the right is unconditional — only the passage of time is required before payment is due. Choice A is incorrect because both contract assets and receivables may be classified as current or noncurrent depending on expected timing.', 'easy', 1),

-- Q9: hard / L4 — Repurchase agreement with call option treated as lease
(2, 'Revenue Recognition', 'Deerfield Manufacturing sells industrial equipment to Summit Corp for $400,000. The contract includes a call option allowing Deerfield to repurchase the equipment within 18 months for $380,000. The original cost was $280,000 and the expected market value at the option date is $350,000. Under ASC 606, how should Deerfield account for this transaction at inception?', '["As a lease, because the repurchase price is less than the original selling price and the customer has a significant economic incentive to return the asset", "As a sale with a separate put option valued at $20,000", "As a sale with full revenue of $400,000, because the call option is at the entity''s discretion", "As a financing arrangement with $400,000 recorded as a liability"]'::jsonb, 0, 'Under ASC 606-10-55-70 through 55-72, when an entity has a call option to repurchase an asset at a price lower than the original selling price, the arrangement is accounted for as a lease if the customer has a significant economic incentive to return the asset. Since $380,000 < $400,000 and exceeds expected market value ($350,000), the customer benefits from returning it. Choice C is incorrect because ASC 606 requires evaluating the economic substance of repurchase options regardless of which party holds the option.', 'hard', 4),

-- Q10: hard / L4 — Contract combination and subsequent modification as separate contract
(2, 'Revenue Recognition', 'Ridgeline Engineering enters two contracts with Beacon Corp on the same day: Contract A for design services ($300,000) and Contract B for construction ($700,000). The contracts were negotiated as a package with interdependent pricing, and the services form a single performance obligation. Six months later, Beacon requests additional design work worth $50,000 at standalone price that is distinct from the original services. Under ASC 606, how should Ridgeline account for the combination and modification?', '["Keep all three contracts separate because each was individually negotiated", "Combine Contracts A and B and treat the modification as a cumulative catch-up adjustment", "Combine Contracts A and B into a single $1,000,000 contract, and treat the modification as a separate contract because it adds distinct services at standalone selling price", "Combine all three items into a single $1,050,000 contract with prospective reallocation"]'::jsonb, 2, 'Under ASC 606-10-25-9, contracts negotiated as a package where consideration depends on the other and goods/services form a single performance obligation must be combined. Under ASC 606-10-25-12, the modification adding $50,000 of distinct services at standalone selling price is treated as a separate contract. Choice B is incorrect because the cumulative catch-up method applies only when modification goods are not distinct from those already transferred.', 'hard', 4),

-- Q11: easy / L1 — Nonrefundable upfront fees allocated to performance obligations
(2, 'Revenue Recognition', 'Under ASC 606, how are nonrefundable upfront fees (such as activation or setup fees) generally accounted for?', '["Recognized as revenue immediately upon receipt because they are nonrefundable", "Included in the transaction price and allocated to identified performance obligations, often recognized over the period of expected service", "Recognized as a separate performance obligation for the setup activity", "Excluded from the transaction price and reported as other income"]'::jsonb, 1, 'Under ASC 606-10-55-51, nonrefundable upfront fees generally do not represent a transfer of a distinct good or service. They are included in the transaction price and allocated to the identified performance obligations, typically recognized over the period the customer receives the related services. Choice A is incorrect because nonrefundability does not determine the timing of revenue recognition — the transfer of goods or services does.', 'easy', 1),

-- Q12: medium / L3 — Output vs input method yield different revenue amounts
(2, 'Revenue Recognition', 'Northgate Builders has a $12 million contract to construct a parking garage qualifying for over-time recognition. Four of 10 planned floors are complete. Costs incurred are $2.8 million of an estimated $8 million total. Under ASC 606, how would the choice between an output method and an input method affect revenue recognized to date?', '["Both methods yield the same revenue because the contract price is fixed", "The output method yields $4.8 million and the input method yields $3.5 million; only the input method is permitted", "Only the input method is permitted for construction contracts under ASC 606", "The output method yields $4.8 million (4/10 × $12M) and the input method yields $4.2 million ($2.8M/$8M × $12M); the entity selects whichever faithfully depicts performance"]'::jsonb, 3, 'Under ASC 606-10-25-33 through 25-37, entities select an output or input method that faithfully depicts the transfer of goods or services. Output (4/10 = 40% × $12M = $4.8M) and input ($2.8M/$8M = 35% × $12M = $4.2M) methods can yield different results. Choice C is incorrect because ASC 606 permits both output and input methods — the entity selects the approach that best represents actual progress.', 'medium', 3),

-- Q13: hard / L3 — Variable consideration penalty constrained due to limited experience
(2, 'Revenue Recognition', 'Oakdale Consulting enters a $600,000 contract to implement an ERP system for Pinecrest Corp. The contract includes a $90,000 penalty if the system is not operational by June 30. Oakdale estimates a 35% probability of missing the deadline. Oakdale has limited experience with this type of project. Under ASC 606, what transaction price should Oakdale recognize at inception?', '["$600,000, because penalties are not included in variable consideration until incurred", "$510,000, because the constraint requires exclusion of the full $90,000 penalty given the limited experience and high uncertainty", "$568,500, using the expected value method and ignoring the constraint because the estimate is probability-weighted", "$600,000, with the $90,000 disclosed as a contingent liability under ASC 450"]'::jsonb, 1, 'Under ASC 606-10-32-11, variable consideration is constrained to amounts where a significant revenue reversal is not probable. With limited experience and a 35% penalty probability, including any portion of the uncertain amount could lead to a significant reversal. The full $90,000 penalty is excluded, resulting in $510,000. Choice C is incorrect because the constraint applies independently of the estimation method — probability weighting alone does not satisfy the constraint analysis.', 'hard', 3),

-- Q14: medium / L2 — Residual approach permitted when SSP is highly variable
(2, 'Revenue Recognition', 'Vanguard Tech sells a hardware device and a new cloud service in a bundle for $750. The device has an observable standalone selling price of $500. The cloud service was just launched with no observable price, and its selling price is highly variable. Under ASC 606, which approach should Vanguard use to estimate the cloud service''s standalone selling price?', '["Adjusted market assessment approach, estimating what the market would pay", "Expected cost plus a margin approach, forecasting costs and adding a margin", "Residual approach, allocating the remaining $250 to the cloud service", "Proportional approach, splitting the bundle price equally between the two obligations"]'::jsonb, 2, 'Under ASC 606-10-32-34, the residual approach is permitted when the standalone selling price of a good or service is highly variable or uncertain. Since the cloud service was just launched with no observable price and high variability, the residual approach allocates $750 − $500 = $250 to it. Choice A is incorrect because the adjusted market assessment approach requires sufficient market data, which is unavailable for a newly launched service with highly variable pricing.', 'medium', 2),

-- Q15: easy / L2 — Expected value method probability-weighted calculation
(2, 'Revenue Recognition', 'Glenbrook Consulting enters a $200,000 contract that includes a performance bonus. There is a 60% probability the bonus will be $40,000 and a 40% probability it will be $0. Under ASC 606, what is the expected value of the variable consideration?', '["$24,000", "$40,000", "$16,000", "$20,000"]'::jsonb, 0, 'Under ASC 606-10-32-8, the expected value method calculates a probability-weighted amount: (60% × $40,000) + (40% × $0) = $24,000. This method is appropriate when there are multiple possible outcomes. Choice B is incorrect because $40,000 is the most likely single outcome, which would be used under the most likely amount method rather than the expected value approach.', 'easy', 2),

-- Q16: medium / L3 — Significant integration service prevents goods from being distinct
(2, 'Revenue Recognition', 'Ironclad Systems enters a contract to deliver custom software, hardware integration, and data migration to Bellmont Healthcare. Each component has standalone value, but the contract requires Ironclad to provide a significant integration service that combines all three into a unified hospital management system. Under ASC 606, how should Ironclad identify the performance obligations?', '["Three separate performance obligations because each has standalone value", "Two performance obligations: the integration service and the combined deliverables", "Three separate performance obligations with the integration service recognized ratably", "One combined performance obligation because the significant integration service means the components are not separately identifiable from each other"]'::jsonb, 3, 'Under ASC 606-10-25-21(b), even when goods or services are individually capable of providing benefit, they are not distinct if the entity provides a significant integration service. The integration substantially modifies each component, making them not separately identifiable. All items form a single performance obligation. Choice A is incorrect because the ''capable of being distinct'' criterion alone is insufficient — goods must also be ''separately identifiable'' within the contract context.', 'medium', 3),

-- Q17: easy / L1 — Physical possession as indicator of control transfer
(2, 'Revenue Recognition', 'Under ASC 606, which of the following is an indicator that control of a good has transferred to the customer at a point in time?', '["The entity has incurred costs related to the good", "The entity has issued an invoice to the customer", "The customer has physical possession of the asset", "The entity has completed production of the good"]'::jsonb, 2, 'Under ASC 606-10-25-30, indicators of control transfer include physical possession, legal title, risks and rewards of ownership, customer acceptance, and present right to payment. Physical possession is a direct indicator. Choice A is incorrect because the entity''s cost incurrence relates to its own performance, not to whether control has transferred to the customer.', 'easy', 1),

-- Q18: medium / L2 — Functional IP recognized at point in time
(2, 'Revenue Recognition', 'Silverpeak Studios licenses a completed film to StreamMax for three years. Silverpeak will not update or modify the film during the license period, and the film''s value does not depend on Silverpeak''s ongoing activities. Under ASC 606, how should Silverpeak classify and recognize revenue from this license?', '["As symbolic IP with revenue recognized over the three-year license period", "As functional IP with revenue recognized at the point in time the license is transferred", "As symbolic IP with revenue recognized only when StreamMax reports viewership data", "As functional IP with revenue recognized using the cost-to-cost method over three years"]'::jsonb, 1, 'Under ASC 606-10-55-58 through 55-62, a license is classified as functional IP when it has significant standalone functionality and the licensor does not undertake activities that significantly affect the IP. A completed film with no ongoing modifications is functional IP, recognized at the point of transfer. Choice A is incorrect because symbolic IP requires the licensor''s ongoing activities to significantly affect the value of the IP, which is not the case here.', 'medium', 2),

-- Q19: hard / L4 — Discount allocated to specific performance obligations with observable evidence
(2, 'Revenue Recognition', 'Meridian Tech sells three products in a bundle for $270,000: Product X (SSP $120,000), Product Y (SSP $80,000), and Product Z (SSP $120,000). Products Y and Z are regularly sold together for $150,000 (a $50,000 discount from their combined SSP of $200,000). The overall bundle discount is $50,000. Under ASC 606, how should Meridian allocate the discount?', '["Proportionally across all three products based on relative standalone selling prices", "Entirely to Product X because it has the highest standalone selling price", "Equally across the three products at $16,667 each", "Entirely to Products Y and Z because observable evidence shows the discount belongs to those two products"]'::jsonb, 3, 'Under ASC 606-10-32-36 through 32-38, a discount is allocated entirely to one or more (but not all) performance obligations when observable evidence shows the discount relates to specific obligations. Since Products Y and Z are regularly sold together at a $50,000 discount matching the overall bundle discount, the entire discount is allocated to Y and Z. Choice A is incorrect because proportional allocation is the default but is overridden when observable evidence demonstrates the discount belongs to specific performance obligations.', 'hard', 4),

-- Q20: medium / L2 — Consignment arrangement delays revenue until end-customer sale
(2, 'Revenue Recognition', 'Fieldstone Furniture delivers 50 sofas to HomeStyle Showroom under an arrangement where HomeStyle displays the sofas and remits payment only as units are sold to end customers. HomeStyle can return unsold sofas at any time. Under ASC 606, when should Fieldstone recognize revenue?', '["When the end customer purchases a sofa from HomeStyle, because the arrangement is a consignment and control has not transferred to HomeStyle", "When Fieldstone delivers the sofas to HomeStyle, because physical possession has transferred", "Ratably over the expected selling period of the inventory", "When HomeStyle accepts the sofas and places them on the showroom floor"]'::jsonb, 0, 'Under ASC 606-10-55-80, indicators of a consignment arrangement include the ability to return the product, lack of obligation to pay until goods are sold, and entity control over inventory. Since HomeStyle can return unsold sofas and only pays upon sale, this is a consignment — control remains with Fieldstone until end-customer purchase. Choice B is incorrect because physical delivery alone does not transfer control when consignment indicators are present.', 'medium', 2),

-- Q21: hard / L4 — Right of return creates both refund liability and asset for returned products
(2, 'Revenue Recognition', 'Lakewood Electronics sells 2,000 headphones at $75 each ($150,000 total) with a 60-day return right. Historical data indicates a 10% return rate. The cost per unit is $45. Under ASC 606, what is the refund liability and the asset for the right to recover returned products that Lakewood should recognize?', '["Refund liability of $15,000 and asset of $15,000", "Refund liability of $15,000 and no separate asset", "Refund liability of $15,000 and asset of $9,000", "Refund liability of $6,000 and asset of $9,000"]'::jsonb, 2, 'Under ASC 606-10-55-27, the entity recognizes a refund liability for expected returns (10% × $150,000 = $15,000) and a separate asset for the right to recover products from customers (10% × 2,000 units × $45 cost = $9,000). Revenue is recognized for 90% of sales ($135,000). Choice B is incorrect because ASC 606 requires a separate asset for the expected cost of returned inventory, distinct from the refund liability.', 'hard', 4),

-- Q22: medium / L3 — Contract combination when pricing is interdependent
(2, 'Revenue Recognition', 'Stonebridge Design enters two contracts with Maple Hotels on the same day: one for lobby renovation ($400,000) and another for exterior landscaping ($100,000). The landscaping scope was added as a concession during the lobby renovation negotiation, and the landscaping fee was reduced from its standalone price of $150,000. Under ASC 606, should these contracts be combined?', '["Yes, because the contracts were negotiated as a package and the consideration of one depends on the pricing of the other", "No, because the services in each contract are distinct and separately identifiable", "Yes, but only if the contracts are formally merged into one written agreement", "No, because combining is only required when the promised goods or services form a single performance obligation"]'::jsonb, 0, 'Under ASC 606-10-25-9, contracts entered at or near the same time with the same customer are combined when any of three criteria are met, including that the contracts are negotiated as a package or the consideration in one depends on the other. The reduced landscaping fee indicates pricing interdependence. Choice B is incorrect because contract combination is determined by the relationship between contracts, not by whether individual services are distinct.', 'medium', 3),

-- Q23: medium / L3 — Stand-ready obligation satisfies over-time criterion
(2, 'Revenue Recognition', 'Evergreen Security enters a 24-month contract to provide continuous monitoring and threat response to Greystone Bank for $240,000. Evergreen must stand ready to respond to security incidents at any time, though the timing and frequency of incidents are unpredictable. Under ASC 606, how should Evergreen recognize revenue?', '["At a point in time when each security incident is resolved", "Over time using a time-elapsed measure, because the stand-ready obligation transfers a service the customer simultaneously receives and consumes", "At the end of the 24-month contract when the full service period is complete", "Using an output method based on the number of incidents responded to"]'::jsonb, 1, 'Under ASC 606-10-25-27 and 55-18, a stand-ready obligation (where the entity must be available to perform as needed) satisfies the ''simultaneously receives and consumes'' criterion for over-time recognition. A time-elapsed measure faithfully depicts the transfer because the customer benefits from availability each day. Choice A is incorrect because the performance obligation is the continuous readiness, not individual incident responses.', 'medium', 3),

-- Q24: hard / L4 — Customer acceptance clause delays revenue when entity cannot objectively verify specs
(2, 'Revenue Recognition', 'Primewave Technologies delivers a customized data analytics platform to Cascade Financial for $800,000. The contract includes a formal acceptance clause requiring Cascade to test the platform over 30 days and confirm it meets specifications. Primewave has not delivered similar platforms before and cannot objectively determine whether specifications are met. Under ASC 606, when should Primewave recognize revenue?', '["Upon physical delivery, because the customer has taken possession", "Ratably over the 30-day testing period as acceptance becomes more probable", "Upon substantial completion of the platform, because acceptance is a formality", "Upon customer acceptance, because Primewave cannot objectively determine that specifications are met and acceptance is not a formality"]'::jsonb, 3, 'Under ASC 606-10-25-30(e) and 55-86 through 55-89, when customer acceptance is not a formality and the entity cannot objectively determine that the asset meets specifications, control does not transfer until acceptance occurs. Without prior experience delivering similar platforms, Primewave cannot conclude acceptance is a formality. Choice C is incorrect because acceptance cannot be treated as a formality when the entity lacks objective evidence that specifications are met.', 'hard', 4),

-- Q25: medium / L2 — Nonmonetary exchange scope exclusion for same-line-of-business exchanges
(2, 'Revenue Recognition', 'Whitfield Auto Parts agrees to exchange 500 brake assemblies with Kensington Motors for 500 alternators. Both companies regularly sell these parts to customers, and the exchange is made to reduce shipping costs. The fair values are approximately equal. Under ASC 606, does this transaction meet the contract criteria?', '["No, because ASC 606 excludes nonmonetary exchanges between parties in the same line of business made to facilitate sales to customers", "Yes, because both parties have approved the exchange and each party''s obligations are identifiable", "No, because ASC 606 applies only to contracts involving cash consideration", "Yes, because the parts have readily determinable fair values"]'::jsonb, 0, 'Under ASC 606-10-15-2(e), nonmonetary exchanges between parties in the same line of business made to facilitate sales to customers or potential customers are excluded from ASC 606. This exchange of similar inventory to reduce shipping costs falls within this exclusion. Choice D is incorrect because having determinable fair values does not override the scope exclusion for nonmonetary exchanges that facilitate sales in the same line of business.', 'medium', 2),

-- Q26: medium / L2 — Practical expedient allows expensing contract costs when amortization ≤ 1 year
(2, 'Revenue Recognition', 'Brookfield Insurance pays its sales agents a $3,000 commission for each new 18-month policy sold and a $1,500 commission for each new 9-month short-term policy. Under ASC 606, how should each commission be accounted for?', '["Both commissions should be expensed immediately as incurred", "The $3,000 commission should be capitalized and amortized over 18 months; the $1,500 commission may be expensed immediately under the practical expedient", "Both commissions should be capitalized and amortized over their respective policy periods", "The $3,000 commission should be expensed immediately; the $1,500 commission should be capitalized"]'::jsonb, 1, 'Under ASC 606-10-25-16A, incremental costs of obtaining a contract may be expensed as incurred if the amortization period is one year or less. The 9-month commission qualifies for this expedient, while the 18-month commission must be capitalized under ASC 606-10-25-16 and amortized. Choice A is incorrect because the $3,000 commission relates to an 18-month contract, exceeding the one-year practical expedient threshold.', 'medium', 2),

-- Q27: easy / L1 — Adjusted market assessment approach evaluates market willingness to pay
(2, 'Revenue Recognition', 'Under ASC 606, when using the adjusted market assessment approach to estimate standalone selling price, what does the entity evaluate?', '["The entity''s expected costs of satisfying the performance obligation plus a reasonable margin", "The residual amount after deducting known standalone selling prices from the transaction price", "The original negotiated price in the contract less any applicable discounts", "The price that customers in the market would be willing to pay for the good or service"]'::jsonb, 3, 'Under ASC 606-10-32-34(a), the adjusted market assessment approach estimates standalone selling price by evaluating the market and estimating the price customers would be willing to pay. Choice A is incorrect because it describes the expected cost plus a margin approach, which is a separate estimation method under ASC 606-10-32-34(b).', 'easy', 1),

-- Q28: easy / L1 — Expected cost plus margin approach builds SSP from entity costs
(2, 'Revenue Recognition', 'Under ASC 606, which standalone selling price estimation method forecasts the entity''s expected costs and adds an appropriate profit margin?', '["Adjusted market assessment approach", "Residual approach", "Expected cost plus a margin approach", "Relative allocation approach"]'::jsonb, 2, 'Under ASC 606-10-32-34(b), the expected cost plus a margin approach estimates standalone selling price by forecasting costs to satisfy the performance obligation and adding an appropriate margin. Choice A is incorrect because the adjusted market assessment approach looks to the broader market to determine what customers would pay, rather than building up from the entity''s costs.', 'easy', 1),

-- Q29: medium / L3 — Contract modification as partial termination with distinct remaining services
(2, 'Revenue Recognition', 'Cascadia Design has a contract with Riverton Hotels to renovate 10 rooms for $200,000. After completing 4 rooms, Riverton cancels the remaining 6 rooms, and both parties agree to a termination payment of $30,000 for work completed beyond what has been billed. The remaining services are distinct from those already transferred. Under ASC 606, how should Cascadia account for this partial termination?', '["As a contract modification that reduces the scope and price, with any difference recognized as revenue in the current period since no remaining obligations exist", "As a breach of contract, with the $30,000 recognized as other income", "By reversing all revenue for the 4 completed rooms and recognizing $30,000 as settlement income", "By continuing to recognize revenue for the original $200,000 over the expected period"]'::jsonb, 0, 'Under ASC 606-10-25-13, a termination that reduces scope and price is treated as a contract modification. Since the remaining services are distinct from those transferred, the modification is accounted for prospectively under ASC 606-10-25-13(a). The revised transaction price covers only the completed scope plus the termination payment, recognized in the period of modification. Choice B is incorrect because ASC 606 treats agreed-upon scope reductions as modifications, not as breach of contract events requiring separate income classification.', 'medium', 3),

-- Q30: easy / L1 — Collectibility criterion requires probable collection
(2, 'Revenue Recognition', 'Under ASC 606, what does the collectibility criterion require when assessing whether a contract with a customer exists?', '["The customer must pay the full amount before the entity begins performance", "It is probable that the entity will collect the consideration to which it is entitled", "The entity must obtain a credit report confirming the customer''s ability to pay", "The customer must provide collateral equal to at least 50% of the contract price"]'::jsonb, 1, 'Under ASC 606-10-25-1(e), one of the five criteria for contract existence is that it is probable the entity will collect substantially all of the consideration to which it will be entitled. This is an assessment of the customer''s ability and intention to pay. Choice A is incorrect because ASC 606 does not require advance payment — it requires a probability assessment of collectibility, not a specific payment arrangement.', 'easy', 1)
;

COMMIT;
